def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        base = DAILY_SALARY * 0.22
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.55
        return max(0, min(budget, base))

    opp_count = len(alive)
    total_players = opp_count + 1
    expected_units = supply / float(WATER_REQ)
    scarcity = total_players - expected_units

    prev_bids = []
    prev_fail_bids = []
    desperate_opp = 0
    rich_opp = 0

    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            status = prev.get('status')
            err = prev.get('error')
            if status not in ('won', 'success', 'alive_ok') or err:
                prev_fail_bids.append(bid)

    if hp <= 1:
        target = DAILY_SALARY * 0.98
    elif no_water >= 2:
        target = DAILY_SALARY * 0.95
    elif hp <= 2 or no_water >= 1:
        target = DAILY_SALARY * 0.82
    else:
        if scarcity <= 0:
            target = DAILY_SALARY * 0.28
        elif scarcity < 1:
            target = DAILY_SALARY * 0.42
        elif scarcity < 2:
            target = DAILY_SALARY * 0.56
        else:
            target = DAILY_SALARY * 0.68

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if hp > 2 and no_water == 0 and highest_prev >= DAILY_SALARY * 0.9:
            target = min(target, DAILY_SALARY * 0.34)
        else:
            target = max(target, min(DAILY_SALARY * 0.92, avg_prev + 2.0))
            if prev_fail_bids:
                target = max(target, min(DAILY_SALARY * 0.95, max(prev_fail_bids) + 3.0))

    if desperate_opp >= max(1, opp_count // 2):
        target += 4.0
    if rich_opp >= max(1, opp_count // 2):
        target += 3.0
    if supply >= 23:
        target -= 5.0
    elif supply <= 17:
        target += 5.0

    reserve_floor = 0.0
    if hp > 2 and no_water == 0:
        reserve_floor = budget * 0.55
    elif hp > 1:
        reserve_floor = budget * 0.35
    spend_cap = max(0.0, budget - reserve_floor)

    if hp <= 2 or no_water >= 1:
        spend_cap = budget

    bid = min(target, spend_cap if spend_cap > 0 else budget)
    if bid < 0:
        bid = 0
    if hp <= 1 or no_water >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    return max(0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, take safe minimum to stay alive.
    if not alive_opps:
        target = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, target)

    # Read yesterday bids (immediate reaction only).
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how tight supply is; higher supply lets us bid less.
    # supply is in [15,25]; map to 0..1.
    tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    tightness = max(0.0, min(1.0, tightness))

    # Determine aggressiveness based on their previous bid.
    # If they were near our salary, they likely expect to win; we respond with a near-just-enough bid.
    aggressive = highest_prev_bid >= DAILY_SALARY * 0.85

    # Base bid level: mid when not aggressive, higher when aggressive.
    # Also scale with our hp and no-water tolerance.
    if aggressive:
        # If we are healthy, conserve; if low hp or close to failure, bid more.
        if hp <= 2.0 or no_water_days >= 2:
            base = DAILY_SALARY * 0.95
        elif hp <= 3.0:
            base = DAILY_SALARY * 0.75
        else:
            base = DAILY_SALARY * 0.55
    else:
        # Not aggressive: bid around a fraction of salary, slightly higher when supply is tight.
        base = DAILY_SALARY * (0.40 + 0.20 * tightness)

    # Try to outbid their last highest by a small increment when we have budget.
    # Keep increment small to avoid overpaying.
    increment = 1.5 + 2.0 * tightness
    desired = base
    if highest_prev_bid > 0.0:
        desired = max(desired, highest_prev_bid + increment)

    # If we are in danger, ensure we bid enough to secure water.
    # (We don't know exact scoring, so we use a conservative boost.)
    if hp <= 1.5 or no_water_days >= 3:
        desired = max(desired, DAILY_SALARY * 0.90)

    # Cap by budget.
    if budget <= 0.0:
        return 0.0

    bid = min(budget, desired)
    # Ensure non-negative and not absurd.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    max_prev_bid = 0
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    if hp <= 2 or no_water_days >= 2:
        # desperate: bid high but within budget
        return min(budget, DAILY_SALARY * 0.95)
    if max_prev_bid > 0 and max_prev_bid < DAILY_SALARY * 0.7:
        # exploit by bidding slightly higher
        return min(budget, max_prev_bid + 5)
    # default: moderate bid
    return min(budget, DAILY_SALARY * 0.55)
